{"file_path":"tests/test_spec.py","content":""""Behavioral checks for each section of SPEC.md."""
import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group, flags_in_window, longest_flag_streak,
    monitor_flag_rate, pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_section_1_none_and_empty():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_section_2_weighted_pooled_rate():
    groups = {"a": [event("a", 1, True)],
              "b": [event("b", 1, False)] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({}) == 0.0
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_section_3_window():
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 1) == 3
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 10) == 6
    assert flags_in_window([], 1) == 0


def test_section_4_parse_and_skip():
    lines = ["\n", "  # comment, not, a record", "  a  ,  -2 , 1 \n",
             "b, 0, 0", "c, 1,   ", "  \t  "]
    assert parse_transcript_log(lines) == [event("a", -2, True),
                                           event("b", 0, False),
                                           event("c", 1, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,yes"])
def test_section_4_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", " ", "ok,1,0", bad_line])


def test_section_5_duplicate_ids_last_wins_and_sorted():
    first = event("a", 9, True)
    last = event("a", 2, None)
    b = event("b", 2, True)
    c = event("c", 1, False)
    assert dedupe_transcripts([first, b, c, last]) == [c, last, b]
    assert dedupe_transcripts([]) == []


def test_section_6_daily_counts():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 2, None), event("e", 3, False), event("f", 4, True)]
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 4, 3) == []


def test_section_7_summary():
    events = [event("a", 1, True), event("b", 2, False), event("c", 4, True)]
    groups = {"a": events, "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 1}
    assert monitor_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 1}
    assert monitor_summary(groups, 10)["recent"] == 2
    assert monitor_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({"a": [event("x", 1, True)],
                            "b": [event("y", 1, False)] * 3}, 1)["rate"] == 0.25


def test_section_8_ranking():
    groups = {"z": [event("z", 1, True)], "a": [event("a", 1, True)],
              "empty": [], "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 5) == []


def test_section_9_group_rates():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert list(result) == ["a", "b", "z"]
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert flag_rate_by_group({}) == {}


def test_section_10_streak():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([1, 0, 1]) == 1
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
